export function assetsForPair(pair){return [...new Set(pair.flatMap(id=>{if(!ROSTER[id])throw new Error('Unknown fighter: '+id);return ROSTER[id].assets;}))];}
export class AssetLoader{
 constructor(manifest=ASSET_MANIFEST,imageFactory=()=>new Image()){this.manifest=manifest;this.imageFactory=imageFactory;this.pending=new Map();this.loaded=new Map();}
 load(id){if(this.pending.has(id))return this.pending.get(id);const url=this.manifest[id];if(!url)return Promise.reject(new Error('Missing asset: '+id));let promise=new Promise((resolve,reject)=>{const image=this.imageFactory();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Không tải được '+id+'. Kiểm tra thư mục assets hoặc chạy bằng máy chủ cục bộ.'));image.src=url;});promise=promise.then(image=>{this.loaded.set(id,image);return image;}).catch(error=>{if(this.pending.get(id)===promise)this.pending.delete(id);throw error;});this.pending.set(id,promise);return promise;}
 async loadPair(pair){const ids=assetsForPair(pair),values=await Promise.all(ids.map(id=>this.load(id)));return Object.fromEntries(ids.map((id,i)=>[id,values[i]]));}
 retain(ids){const keep=new Set(ids);for(const id of this.loaded.keys())if(!keep.has(id)){this.loaded.delete(id);this.pending.delete(id);}}
}
